examples.code:
const response = await fetch('http://localhost:8000/v1/system/info');
const data = await response.json();
console.log(data);

const response = await fetch('http://localhost:8000/v1/system/live');
const data = await response.json();
console.log(data);

const response = await fetch('http://localhost:8000/v1/system/plan', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ model: 'bonsai-4b-gguf-q1_0' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/system/plan")
    .json(&serde_json::json!({"model": "bonsai-4b-gguf-q1_0"}))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

const response = await fetch('http://localhost:8000/v1/system/permission');
const data = await response.json();
console.log(data);

const response = await fetch('http://localhost:8000/v1/system/permission', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    wasm_firewall: 'strict',
    vectorize_user_input: true,
    stream_telemetry: false
  })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/system/permission")
    .json(&serde_json::json!({
        "wasm_firewall": "strict",
        "vectorize_user_input": true,
        "stream_telemetry": false
    }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

const response = await fetch('http://localhost:8000/v1/system/cmd', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ command: 'echo Hello cluaiz' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/system/cmd")
    .json(&serde_json::json!({
        "command": "echo Hello cluaiz" }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);
